const tabId = 1854033397;
const petDetails = await browserjs(tabId, () => {
  // Find all pet cards or sections
  const cards = Array.from(document.querySelectorAll('a[href*="/details/"]')).map(a => {
    let container = a.closest('div[class*="pet"], div[class*="card"], li, article') || a.parentElement;
    while (container && container.parentElement && container.offsetHeight < 200) {
      container = container.parentElement;
    }
    return {
      href: a.href,
      text: container ? container.innerText : a.innerText
    };
  });

  // Deduplicate by href
  const unique = [];
  const seen = new Set();
  for (const c of cards) {
    if (!seen.has(c.href)) {
      seen.add(c.href);
      unique.push(c);
    }
  }
  return unique.slice(0, 5);
});
console.log("Pet details sample:", JSON.stringify(petDetails, null, 2));

