const tabId = 1854033397;
const trampUrl = "https://www.petfinder.com/dog/tramp-2bc4621f-562e-467e-8b76-0f22cae8f7fc/ca/merced/kitten-tales-rescue-ca2986/details/";
const trampInfo = await browserjs(tabId, async (url) => {
  const res = await fetch(url);
  const text = await res.text();
  const parser = new DOMParser();
  const doc = parser.parseFromString(text, 'text/html');
  const nextDataEl = doc.getElementById('__NEXT_DATA__');
  if (!nextDataEl) return "No next data";
  const json = JSON.parse(nextDataEl.textContent);
  const p = json.props?.pageProps?.animal;
  return {
    id: p?.animalId,
    name: p?.animalName,
    breed: (p?.physical?.breed?.primary || '') + (p?.physical?.breed?.secondary ? ' & ' + p.physical.breed.secondary : '') + (p?.physical?.breed?.mixed ? ' Mix' : ''),
    age: p?.physical?.age?.label,
    sex: p?.physical?.sex,
    size: p?.physical?.size?.label,
    coatLength: p?.physical?.coatLength,
    distance: p?.distance,
    city: p?._location?.address?.city || p?.organization?.organizationCity,
    state: p?._location?.address?.state || p?.organization?.organizationState,
    shelter: p?.organization?.organizationName,
    publishTime: p?.meta?.publishTime,
    intakeDate: p?.residency?.intakeDate,
    statusChangeDate: p?.residency?.adoptionStatusChangeDate,
    goodWith: {
      dogs: p?.behavior?.interactions?.dogs,
      cats: p?.behavior?.interactions?.cats,
      childrenUnder8: p?.behavior?.interactions?.childrenUnder8,
      children8AndUp: p?.behavior?.interactions?.children8AndUp
    }
  };
}, trampUrl);
console.log("Tramp info:", JSON.stringify(trampInfo, null, 2));

